package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {
    private static final long serialVersionUID = 1L;

    public long time;              // Column 0: timestamp in microseconds
    public String missingInfo;     // Column 1: missing info flag
    public long jobId;             // Column 2: job ID
    public int taskIdx;            // Column 3: task index
    public long machineId;         // Column 4: machine ID
    public int eventType;          // Column 5: event type (0=SUBMIT, 1=SCHEDULE, 2=EVICT, 3=FAIL, 4=FINISH, 5=KILL, 6=LOST)
    public String user;            // Column 6: user (hashed)
    public int schedulingClass;    // Column 7: scheduling class
    public int priority;           // Column 8: priority
    public double cpuRequested;    // Column 9: CPU requested
    public double memoryRequested; // Column 10: memory requested
    public double diskRequested;   // Column 11: disk space requested
    public int differentMachines;  // Column 12: different machines restriction

    public TaskEvent() {
    }

    public TaskEvent(long time, String missingInfo, long jobId, int taskIdx, long machineId,
                     int eventType, String user, int schedulingClass, int priority,
                     double cpuRequested, double memoryRequested, double diskRequested,
                     int differentMachines) {
        this.time = time;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.taskIdx = taskIdx;
        this.machineId = machineId;
        this.eventType = eventType;
        this.user = user;
        this.schedulingClass = schedulingClass;
        this.priority = priority;
        this.cpuRequested = cpuRequested;
        this.memoryRequested = memoryRequested;
        this.diskRequested = diskRequested;
        this.differentMachines = differentMachines;
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "time=" + time +
                ", jobId=" + jobId +
                ", taskIdx=" + taskIdx +
                ", eventType=" + eventType +
                '}';
    }
}

