package clusterdata.query;

import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.AscendingTimestampsWatermarks;
import org.apache.flink.api.common.eventtime.Watermark;
import org.apache.flink.api.common.functions.FilterFunction;
import org.apache.flink.api.common.functions.FlatMapFunction;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.functions.ReduceFunction;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.core.fs.FileSystem;
import org.apache.flink.streaming.api.TimeCharacteristic;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.datastream.DataStreamSource;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.source.RichSourceFunction;
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    // Custom source function for reading gzipped CSV files
    static class GzipCsvSource<T> extends RichSourceFunction<T> {
        private final String filePath;
        private final boolean isTaskEvent;
        private volatile boolean running = true;

        public GzipCsvSource(String filePath, boolean isTaskEvent) {
            this.filePath = filePath;
            this.isTaskEvent = isTaskEvent;
        }

        @Override
        public void run(SourceContext<T> ctx) throws Exception {
            try (GZIPInputStream gzis = new GZIPInputStream(Files.newInputStream(Paths.get(filePath)));
                 BufferedReader reader = new BufferedReader(new InputStreamReader(gzis))) {

                String line;
                while (running && (line = reader.readLine()) != null) {
                    if (line.trim().isEmpty()) continue;

                    String[] fields = line.split(",");
                    if (isTaskEvent) {
                        TaskEvent event = parseTaskEvent(fields);
                        ctx.collect((T) event);
                    } else {
                        JobEvent event = parseJobEvent(fields);
                        ctx.collect((T) event);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }

        private TaskEvent parseTaskEvent(String[] fields) {
            TaskEvent event = new TaskEvent();
            event.time = parseLong(fields, 0);
            event.missingInfo = parseString(fields, 1);
            event.jobId = parseLong(fields, 2);
            event.taskIdx = parseInt(fields, 3);
            event.machineId = parseLong(fields, 4);
            event.eventType = parseInt(fields, 5);
            event.user = parseString(fields, 6);
            event.schedulingClass = parseInt(fields, 7);
            event.priority = parseInt(fields, 8);
            event.cpuRequested = parseDouble(fields, 9);
            event.memoryRequested = parseDouble(fields, 10);
            event.diskRequested = parseDouble(fields, 11);
            event.differentMachines = parseInt(fields, 12);
            return event;
        }

        private JobEvent parseJobEvent(String[] fields) {
            JobEvent event = new JobEvent();
            event.time = parseLong(fields, 0);
            event.missingInfo = parseString(fields, 1);
            event.jobId = parseLong(fields, 2);
            event.eventType = parseInt(fields, 3);
            event.user = parseString(fields, 4);
            event.schedulingClass = parseInt(fields, 5);
            event.collectionName = parseString(fields, 6);
            event.priority = parseInt(fields, 7);
            return event;
        }

        private long parseLong(String[] fields, int idx) {
            return idx < fields.length && !fields[idx].isEmpty() ? Long.parseLong(fields[idx]) : 0L;
        }

        private int parseInt(String[] fields, int idx) {
            return idx < fields.length && !fields[idx].isEmpty() ? Integer.parseInt(fields[idx]) : 0;
        }

        private double parseDouble(String[] fields, int idx) {
            return idx < fields.length && !fields[idx].isEmpty() ? Double.parseDouble(fields[idx]) : 0.0;
        }

        private String parseString(String[] fields, int idx) {
            return idx < fields.length ? fields[idx] : "";
        }
    }

    // Class to track a session: jobId, stage start time, and list of task events
    static class SessionInfo {
        public long jobId;
        public long taskCount;

        public SessionInfo(long jobId, long taskCount) {
            this.jobId = jobId;
            this.taskCount = taskCount;
        }

        @Override
        public String toString() {
            return "(" + jobId + "," + taskCount + ")";
        }
    }

    // Class to track the longest stage per job
    static class JobLongestStage {
        public long jobId;
        public long longestStageTaskCount;

        public JobLongestStage(long jobId, long longestStageTaskCount) {
            this.jobId = jobId;
            this.longestStageTaskCount = longestStageTaskCount;
        }

        @Override
        public String toString() {
            return "(" + jobId + "," + longestStageTaskCount + ")";
        }
    }

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  "+taskInput);
        System.out.println("job_input  "+jobInput);
        final long sesssize = params.getLong("sesssize", 600) * 1_000_000L;  // Convert seconds to microseconds

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setStreamTimeCharacteristic(TimeCharacteristic.EventTime);

        // Read task events from gzipped CSV
        DataStreamSource<TaskEvent> taskEvents = env.addSource(
            AppBase.taskSourceOrTest(new GzipCsvSource<>(taskInput, true))
        );

        // Filter for SUBMIT events (eventType == 0) and assign timestamps
        DataStream<TaskEvent> submitEvents = taskEvents
            .filter((FilterFunction<TaskEvent>) event -> event.eventType == 0)  // SUBMIT events only
            .assignTimestampsAndWatermarks(
                new AscendingTimestampsWatermarks<TaskEvent>() {
                    @Override
                    public long extractTimestamp(TaskEvent element) {
                        return element.time;
                    }

                    @Override
                    public Watermark getCurrentWatermark() {
                        return new Watermark(Long.MAX_VALUE - 1);
                    }
                }
            );

        // Map to (jobId, 1) for counting
        DataStream<org.apache.flink.api.java.tuple.Tuple2<Long, Long>> jobTaskCounts = submitEvents
            .map(new MapFunction<TaskEvent, org.apache.flink.api.java.tuple.Tuple2<Long, Long>>() {
                @Override
                public org.apache.flink.api.java.tuple.Tuple2<Long, Long> map(TaskEvent event) {
                    return new org.apache.flink.api.java.tuple.Tuple2<>(event.jobId, 1L);
                }
            });

        // Use session windows to group tasks that are close together in time
        // Window closes after sesssize microseconds of inactivity
        DataStream<SessionInfo> sessionCounts = jobTaskCounts
            .keyBy(0)  // Group by jobId
            .window(EventTimeSessionWindows.withGap(org.apache.flink.streaming.api.windowing.time.Time.microseconds(sesssize)))
            .process(new ProcessWindowFunction<
                org.apache.flink.api.java.tuple.Tuple2<Long, Long>,
                SessionInfo,
                org.apache.flink.api.java.tuple.Tuple2<Long, Long>,
                TimeWindow>() {
                @Override
                public void process(
                    org.apache.flink.api.java.tuple.Tuple2<Long, Long> key,
                    ProcessWindowFunction<
                        org.apache.flink.api.java.tuple.Tuple2<Long, Long>,
                        SessionInfo,
                        org.apache.flink.api.java.tuple.Tuple2<Long, Long>,
                        TimeWindow>.Context context,
                    Iterable<org.apache.flink.api.java.tuple.Tuple2<Long, Long>> elements,
                    Collector<SessionInfo> out) {
                    long count = 0;
                    for (org.apache.flink.api.java.tuple.Tuple2<Long, Long> element : elements) {
                        count += element.f1;
                    }
                    out.collect(new SessionInfo(key.f0, count));
                }
            });

        // Find the longest stage per job
        DataStream<JobLongestStage> longestStages = sessionCounts
            .keyBy(0)  // Group by jobId
            .reduce(new ReduceFunction<SessionInfo>() {
                @Override
                public SessionInfo reduce(SessionInfo value1, SessionInfo value2) {
                    if (value2.taskCount > value1.taskCount) {
                        return value2;
                    }
                    return value1;
                }
            })
            .map(new MapFunction<SessionInfo, JobLongestStage>() {
                @Override
                public JobLongestStage map(SessionInfo session) {
                    return new JobLongestStage(session.jobId, session.taskCount);
                }
            });

        // Write output
        longestStages.addSink(AppBase.sinkOrTest(
            longestStages.writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE).getName()
        ));

        env.execute("LongestSessionPerJob");
    }

}

